// spec: specs/notifications.md
// seed: tests/seed.client.spec.ts
import { test, expect } from '@playwright/test';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/client.json') });

const WHITE = 'rgb(255, 255, 255)';

test.describe('התראות — לחיצה על התראה', () => {
  test('לקוח: לחיצה על התראת עסקה ב"ממתין לפעולה" פותחת את העסקה, "חזרה" — להתראות @mobile @data (#ccd9d865)', async ({ page }) => {
    // 1. /wallet → פעמון → /notifications
    await page.goto('/wallet');
    await page.getByTestId('notifications-button').click();
    await expect(page).toHaveURL(/\/notifications$/);

    // 2. פילטר "ממתין לפעולה"
    for (const id of ['chip-all', 'chip-action_required', 'chip-deals', 'chip-wallet']) {
      await expect(page.getByTestId(id)).toBeVisible();
    }
    await expect(page.getByTestId('chip-all')).toContainText('הכל');
    await expect(page.getByTestId('chip-action_required')).toContainText('ממתין לפעולה');
    await expect(page.getByTestId('chip-deals')).toContainText('עסקאות');
    await expect(page.getByTestId('chip-wallet')).toContainText('ארנק');
    await page.getByTestId('chip-action_required').click();

    // 3. הכרטיס הראשון "בקשה לאישור תשלום" / "נדרשת הפקדת כסף"; לזכור את שם העסקה
    const card = page
      .getByTestId(/^notification-[0-9a-f-]{36}$/)
      .filter({ hasText: /בקשה לאישור תשלום|נדרשת הפקדת כסף/ })
      .first();
    await expect(card).toBeVisible();
    const cardTestId = (await card.getAttribute('data-testid'))!;
    const cardText = await card.innerText();
    const dealName = cardText.match(/\n([^\n]+?) · ₪/)![1].trim();

    // 4. ללחוץ על הכרטיס
    await card.click();
    await expect(page).toHaveURL(/\/deals\/[0-9a-f-]{36}$/);
    await expect(page.getByTestId('screen-deal-detail')).toContainText(dealName);

    // 5. "חזרה"; לרענן את הדף
    await page.getByTestId('screen-deal-detail').getByTestId('back-button').click();
    await expect(page).toHaveURL(/\/notifications$/);
    await expect(page.getByTestId(cardTestId)).toHaveCSS('background-color', WHITE);

    await page.reload();
    await expect(page).toHaveURL(/\/notifications$/);
    await expect(page.getByTestId(cardTestId)).toHaveCSS('background-color', WHITE);
  });
});
